let fs = require('fs');

const REPORT_PATH = 'health-report.json';

function validateReport() {
  try {
    const data = fs.readFileSync(REPORT_PATH, 'utf8');
    const report = JSON.parse(data);

    if (report.status !== 'ok') {
      console.error('Validation failed: status is not "ok".');
      process.exit(1);
    }

    if (!Array.isArray(report.checks) || report.checks.length < 2) {
      console.error('Validation failed: checks array is missing or has fewer than 2 entries.');
      process.exit(1);
    }

    console.log('Health report validation successful.');
    process.exit(0);
  } catch (error) {
    console.error('Validation failed due to file read or parsing error:', error.message);
    process.exit(1);
  }
}

validateReport();

